import java.util.concurrent.Executor;
import java.util.concurrent.RejectedExecutionException;
import java.util.concurrent.atomic.AtomicReference;
import org.apache.kafka.clients.producer.Callback;

public class AsyncCallback {
    public static Callback create(Executor executor,Runnable persist,AtomicReference<Throwable> failure) {
        return (metadata,error)->{
            if(error!=null) { failure.compareAndSet(null,error); return; }
            Runnable work=()->{
                try { persist.run(); }
                catch(RuntimeException problem) { failure.compareAndSet(null,problem); }
            };
            try { executor.execute(work); }
            catch(RejectedExecutionException rejected) { failure.compareAndSet(null,rejected); }
        };
    }
}
```

原题知识说明：
常见客户端回调在I/O相关线程执行，长阻塞会拖慢其他完成通知和发送进度。由开发将耗时工作转交有界执行器，验收回调耗时、积压和交付超时，异常需可追踪。

