import java.util.Properties;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.apache.kafka.clients.producer.*;
import org.apache.kafka.common.serialization.StringSerializer;

public class CallbackExperiment {
    static void require(boolean value,String message) { if(!value) throw new AssertionError(message); }
    public static void main(String[] args) throws Exception {
        Properties settings=new Properties();
        settings.put("bootstrap.servers",args[0]);
        settings.put("key.serializer",StringSerializer.class.getName());
        settings.put("value.serializer",StringSerializer.class.getName());
        settings.put("acks","all"); settings.put("linger.ms","0");
        settings.put("delivery.timeout.ms","5000"); settings.put("request.timeout.ms","2000");
        settings.put("max.block.ms","5000");
        CountDownLatch entered=new CountDownLatch(1),gate=new CountDownLatch(1),followup=new CountDownLatch(1);
        AtomicInteger completed=new AtomicInteger();
        AtomicReference<String> businessThread=new AtomicReference<>();
        AtomicReference<Throwable> failure=new AtomicReference<>();
        AtomicReference<Throwable> secondFailure=new AtomicReference<>();
        AtomicLong secondOffset=new AtomicLong(-1);
        ThreadPoolExecutor database=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,
            new ArrayBlockingQueue<>(1),r->{Thread t=new Thread(r,"approved-database-worker");t.setDaemon(true);return t;},
            new ThreadPoolExecutor.AbortPolicy());
        try(KafkaProducer<String,String> producer=new KafkaProducer<>(settings)) {
            Runnable business=()->{
                businessThread.set(Thread.currentThread().getName());entered.countDown();
                try { if(!gate.await(5,TimeUnit.SECONDS)) throw new IllegalStateException("fixture gate timed out"); }
                catch(InterruptedException problem) { Thread.currentThread().interrupt();throw new RuntimeException(problem); }
                completed.incrementAndGet();
            };
            Future<RecordMetadata> first=producer.send(new ProducerRecord<>(args[1],0,"first","payload-a"),
                AsyncCallback.create(database,business,failure));
            try {
                require(entered.await(3,TimeUnit.SECONDS),"database work never started");
                producer.send(new ProducerRecord<>(args[1],0,"second","payload-b"),(metadata,error)->{
                    if(error!=null) secondFailure.set(error); else secondOffset.set(metadata.offset());
                    followup.countDown();
                });
                require(followup.await(1200,TimeUnit.MILLISECONDS),"blocking business callback stalled later producer acknowledgements");
                require(secondFailure.get()==null && secondOffset.get()==1,"second real broker record was not acknowledged");
                require(completed.get()==0,"database work was incorrectly marked complete before gate release");
                require("approved-database-worker".equals(businessThread.get()),"business ran on sender or an unapproved executor");
                System.out.println("NATIVE_KAFKA_JAVA_SECOND_ACK_PROGRESS_WHILE_FIRST_DATABASE_WORK_REMAINS_BLOCKED");
                gate.countDown(); database.shutdown();
                require(database.awaitTermination(3,TimeUnit.SECONDS),"database worker failed to finish");
                require(first.get(3,TimeUnit.SECONDS).offset()==0 && completed.get()==1 && failure.get()==null,"first delivery or business result missing");
                producer.flush();
            } finally { gate.countDown();database.shutdownNow(); }
        } finally { gate.countDown();database.shutdownNow(); }
        AtomicInteger shouldNotRun=new AtomicInteger();
        AtomicReference<Throwable> rejected=new AtomicReference<>();
        Executor full=work->{throw new RejectedExecutionException("bounded queue full");};
        AsyncCallback.create(full,shouldNotRun::incrementAndGet,rejected).onCompletion(null,null);
        require(rejected.get() instanceof RejectedExecutionException && shouldNotRun.get()==0,"queue rejection was hidden or ran on caller");
        AtomicReference<Throwable> sendFailure=new AtomicReference<>();
        Exception brokerError=new org.apache.kafka.common.errors.TimeoutException("controlled producer failure branch");
        AsyncCallback.create(Runnable::run,shouldNotRun::incrementAndGet,sendFailure).onCompletion(null,brokerError);
        require(sendFailure.get()==brokerError && shouldNotRun.get()==0,"delivery failure incorrectly scheduled database work");
        RuntimeException databaseError=new IllegalStateException("controlled database failure");
        AtomicReference<Throwable> captured=new AtomicReference<>();
        AsyncCallback.create(Runnable::run,()->{throw databaseError;},captured).onCompletion(null,null);
        require(captured.get()==databaseError,"background business failure was swallowed");
        AsyncCallback.create(full,()->{},captured).onCompletion(null,null);
        require(captured.get()==databaseError,"later failure overwrote first failure");
        System.out.println("NATIVE_KAFKA_CALLBACK_BOUNDED_EXECUTOR_REJECTION_DELIVERY_FAILURE_AND_BACKGROUND_ERROR_VISIBLE");
    }
}
